    15→int pinctrl_configure_pins(const pinctrl_soc_pin_t *pins,
    16→                        uint8_t pin_cnt,
    17→                        uintptr_t reg)
    18→{
    19→    ARG_UNUSED(reg);
    20→
    21→    for (uint8_t i = 0; i < pin_cnt; i++) {
    22→        pinctrl_soc_pin_t p = pins[i];
    23→        uint8_t gpio = p & 0x3f;
    24→        uint8_t func = (p >> 8) & 0x0f;
    25→        uint32_t val;
    26→
    27→        val = sys_read32(BK7258_GPIO_CFG_BASE + BK_GPIO_CFG_OFF(gpio));
    28→
    29→        if (p & BK7258_FLAG_SECOND_FUNC) {
    30→            val |= BK_GPIO_BIT_2ND_FUNC;
    31→        }
    32→        if (p & BK7258_FLAG_OUTPUT) {
    33→            val &= ~BK_GPIO_BIT_OUTPUT_EN;
    34→        }
    35→        if (p & BK7258_FLAG_INPUT) {
    36→            val |= BK_GPIO_BIT_INPUT_EN;
    37→        }
    38→        if (p & BK7258_FLAG_PULL_UP) {
    39→            val |= BK_GPIO_BIT_PULL_MODE_EN | BK_GPIO_BIT_PULL_MODE;
    40→        }
    41→        if (p & BK7258_FLAG_PULL_DOWN) {
    42→            val |= BK_GPIO_BIT_PULL_MODE_EN;
    43→            val &= ~BK_GPIO_BIT_PULL_MODE;
    44→        }
    45→
    46→        sys_write32(val, BK7258_GPIO_CFG_BASE + BK_GPIO_CFG_OFF(gpio));
    47→
    48→        /* 第一小步：func=0 时不改 perial_mode，保持 bootloader golden state */
    49→        if (func != 0) {
    50→            uint8_t group = gpio / 8;
    51→            uint8_t shift = (gpio % 8) * 4;
    52→            uint32_t addr = BK7258_GPIO_FUNC_MODE_BASE + group * 4;
    53→            uint32_t fval = sys_read32(addr);
    54→
    55→            fval &= ~(0x0fU << shift);
    56→            fval |= ((uint32_t)func << shift);
    57→            sys_write32(fval, addr);
    58→        }
    59→    }
    60→
    61→    return 0;
    62→}
