   220→        }
   221→    }
   222→    ret = pinctrl_apply_state(cfg->pcfg, PINCTRL_STATE_DEFAULT);
   223→    if (ret != 0) {
   224→            return ret;
   225→    }
   226→// #ifdef CONFIG_UART_BK7258_DEBUG   /* 或者直接用 printk */
   227→    printk("pinctrl_apply_state ret=%d pcfg=%p\n", ret, cfg->pcfg);
   228→// #endif
