   247→    val |= BK7258_UART_RX_FIFO_THRESHOLD << BK7258_UART_RX_FIFO_THRESHOLD_SHIFT;
   248→    sys_write32(val, cfg->base + BK7258_UART_FIFO_THRESHOLD_OFFSET);
   249→    cfg->irq_config_func(dev);
   250→#endif
   251→    return 0;
   252→}
